import { getRuntimeConfig } from '@/config/runtime'
import { apiGet } from './http'
import { mockAccessRules, mockMenus } from './mock'
import type { AccessRule, MenuNode } from './models'

export function getMenuTree(rootCode = 'ALL'): Promise<MenuNode[]> {
