import { getRuntimeConfig } from '@/config/runtime'
import { apiGet, apiGetPage } from './http'
import { mockLibraryDetail, mockLibraryPage, mockSharedApps } from './mock'
import type { LibraryDetail, LibraryItem, PagedItems, SharedApp } from './models'

export interface LibraryQuery {
  groupCode?: string
  viewYn?: string
  searchOption?: string
  searchKey?: string
  pageNum?: number
  pageSize?: number
}

export interface SharedAppQuery {
  userId: string
  searchKey?: string
  pageNum?: number
  pageSize?: number
}

export async function getLibraryPage(query: LibraryQuery = {}): Promise<PagedItems<LibraryItem>> {
  if (getRuntimeConfig().mockMode) return mockLibraryPage(query)
  const response = await apiGetPage<LibraryItem[]>('/library', {
    params: { ...query, pageNum: query.pageNum || 1, pageSize: query.pageSize || 10 },
  })
  return { items: response.body || [], ...response.pageInfo }
}

export async function getLibraryDetail(id: number): Promise<LibraryDetail> {
  if (getRuntimeConfig().mockMode) return mockLibraryDetail(id)
  return apiGet<LibraryDetail>(`/library/${encodeURIComponent(id)}`)
}

export async function getSharedApps(query: SharedAppQuery): Promise<PagedItems<SharedApp>> {
  if (!query.userId.trim()) return { items: [], pageNum: 1, pageSize: query.pageSize || 10, totalCount: 0 }
  if (getRuntimeConfig().mockMode) return mockSharedApps(query)
  const response = await apiGetPage<{ appList?: SharedApp[] }>('/app-management/share', {
    params: { ...query, pageNum: query.pageNum || 1, pageSize: query.pageSize || 10 },
  })
  return { items: response.body?.appList || [], ...response.pageInfo }
}
export interface RuntimeConfig {
  appName: string
  environment: string
  backendBaseUrl: string
  authSsoUrl: string
  authLogoutUrl?: string
  mockMode: boolean
  enablePolicyWrites: boolean
  enableMonitoring: boolean
  requestTimeoutMs: number
  pollIntervalMs: number
  allowedHosts: string[]
}

let runtimeConfig: RuntimeConfig | null = null

function assertString(value: unknown, key: string): asserts value is string {
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${key}는 비어 있지 않은 문자열이어야 합니다.`)
}

// 상대 경로가 실제로 same-origin인지 확인할 때 쓰는 sentinel origin.
const RELATIVE_BASE = 'https://relative.invalid/'
// 평문 http를 예외로 허용하는 개발용 loopback host.
const LOOPBACK_HOSTNAMES = ['localhost', '127.0.0.1', '[::1]']

// allowedHosts 항목은 `host` 또는 `host:port`만 허용하고 비교 가능한 형태로 정규화한다.
function normalizeHostEntry(entry: string, protocol: string): string {
  const trimmed = entry.trim()
  let parsed: URL
  try {
    parsed = new URL(`${protocol}//${trimmed}`)
  } catch {
    throw new Error(`allowedHosts 항목은 host 또는 host:port 형식이어야 합니다: ${entry}`)
  }
  if (parsed.username || parsed.password || parsed.pathname !== '/' || parsed.search || parsed.hash || !parsed.hostname) {
    throw new Error(`allowedHosts 항목은 host 또는 host:port 형식이어야 합니다: ${entry}`)
  }
  return parsed.host
}

function validateNetworkValue(value: string | undefined, key: string, allowedHosts: string[]) {
  if (!value) return
  if (/^https?:\/\//i.test(value)) {
    const url = new URL(value)
    if (url.username || url.password) throw new Error(`${key} URL에는 자격증명을 포함할 수 없습니다.`)
    // access_token 헤더와 cookie를 평문으로 보내지 않도록 loopback 외에는 https만 허용한다.
    if (url.protocol === 'http:' && !LOOPBACK_HOSTNAMES.includes(url.hostname)) {
      throw new Error(`${key}는 https를 사용해야 합니다. 평문 http는 loopback host에서만 허용됩니다.`)
    }
    // host가 아닌 hostname만 비교하면 allowlist된 host의 다른 port로 우회할 수 있다.
    const allowedEntries = allowedHosts.map((entry) => normalizeHostEntry(entry, url.protocol))
    if (!allowedEntries.includes(url.host)) throw new Error(`${key} host(${url.host})가 allowedHosts에 없습니다.`)
    return
  }
  if (!value.startsWith('/') && !value.startsWith('./') && !value.startsWith('../')) {
    throw new Error(`${key}는 상대 경로 또는 허용된 내부 URL이어야 합니다.`)
  }
  // `//evil.test`나 `/\evil.test`는 `/`로 시작하지만 브라우저가 다른 origin으로 해석한다.
  let resolved: URL
  try {
    resolved = new URL(value, RELATIVE_BASE)
  } catch {
    throw new Error(`${key}를 URL로 해석할 수 없습니다.`)
  }
  if (resolved.origin !== new URL(RELATIVE_BASE).origin) {
    throw new Error(`${key}는 다른 origin을 가리킬 수 없습니다.`)
  }
}

export function validateRuntimeConfig(input: unknown): RuntimeConfig {
  if (!input || typeof input !== 'object') throw new Error('runtime config는 JSON 객체여야 합니다.')
  const value = input as Record<string, unknown>

  for (const key of ['appName', 'environment', 'backendBaseUrl', 'authSsoUrl']) assertString(value[key], key)
  for (const key of ['mockMode', 'enablePolicyWrites', 'enableMonitoring']) {
    if (typeof value[key] !== 'boolean') throw new Error(`${key}는 boolean이어야 합니다.`)
  }
  if (value.authLogoutUrl != null && typeof value.authLogoutUrl !== 'string') {
    throw new Error('authLogoutUrl은 문자열이어야 합니다.')
  }

  const requestTimeoutMs = Number(value.requestTimeoutMs)
  const pollIntervalMs = Number(value.pollIntervalMs)
  if (!Number.isInteger(requestTimeoutMs) || requestTimeoutMs < 1000 || requestTimeoutMs > 120000) {
    throw new Error('requestTimeoutMs는 1,000~120,000 사이의 정수여야 합니다.')
  }
  if (!Number.isInteger(pollIntervalMs) || pollIntervalMs < 5000 || pollIntervalMs > 300000) {
    throw new Error('pollIntervalMs는 5,000~300,000 사이의 정수여야 합니다.')
  }

  const allowedHosts = value.allowedHosts
  if (!Array.isArray(allowedHosts) || allowedHosts.some((host) => typeof host !== 'string' || !host.trim())) {
    throw new Error('allowedHosts는 문자열 배열이어야 합니다.')
  }
  // 잘못된 항목이 조용히 무시되지 않도록 절대 URL이 없어도 형식을 검사한다.
  for (const host of allowedHosts as string[]) normalizeHostEntry(host, 'https:')

  const config: RuntimeConfig = {
    appName: value.appName as string,
    environment: value.environment as string,
    backendBaseUrl: value.backendBaseUrl as string,
    authSsoUrl: value.authSsoUrl as string,
    authLogoutUrl: typeof value.authLogoutUrl === 'string' ? value.authLogoutUrl : undefined,
    mockMode: value.mockMode as boolean,
    enablePolicyWrites: value.enablePolicyWrites as boolean,
    enableMonitoring: value.enableMonitoring as boolean,
    requestTimeoutMs,
    pollIntervalMs,
    allowedHosts: allowedHosts as string[],
  }

  validateNetworkValue(config.backendBaseUrl, 'backendBaseUrl', config.allowedHosts)
  validateNetworkValue(config.authSsoUrl, 'authSsoUrl', config.allowedHosts)
  validateNetworkValue(config.authLogoutUrl, 'authLogoutUrl', config.allowedHosts)
  return config
}

export async function loadRuntimeConfig(): Promise<RuntimeConfig> {
  const url = new URL('config/runtime.json', document.baseURI)
  const response = await fetch(url, { cache: 'no-store', credentials: 'same-origin' })
  if (!response.ok) throw new Error(`runtime config 응답 오류: HTTP ${response.status}`)
  runtimeConfig = validateRuntimeConfig(await response.json())
  return runtimeConfig
}

export function setRuntimeConfigForTest(config: RuntimeConfig | null) {
  runtimeConfig = config
}

export function getRuntimeConfig(): RuntimeConfig {
  if (!runtimeConfig) throw new Error('runtime config가 아직 로드되지 않았습니다.')
  return runtimeConfig
}
import { afterEach, describe, expect, it, vi } from 'vitest'
import { AxiosError, type InternalAxiosRequestConfig } from 'axios'
import {
  ApiError,
  apiGet,
  apiGetPage,
  configureHttp,
  extractTokenRecord,
  fallbackErrorMessage,
  isSessionExpired,
  readPageRequest,
  setSessionGenerationSource,
  setUnauthorizedHandler,
  unwrapEnvelope,
  unwrapPageEnvelope,
} from './http'
import type { RuntimeConfig } from '@/config/runtime'

const runtimeConfig = {
  appName: 'Admin V2',
  environment: 'test',
  backendBaseUrl: '/api',
  authSsoUrl: '/sso',
  mockMode: false,
  enablePolicyWrites: false,
  enableMonitoring: false,
  requestTimeoutMs: 1000,
  pollIntervalMs: 30000,
  allowedHosts: [],
} as RuntimeConfig

function stubLocalStorage() {
  vi.stubGlobal('localStorage', {
    getItem: () => null,
    setItem: () => undefined,
    removeItem: () => undefined,
  })
}

describe('unwrapEnvelope', () => {
  it('backend body를 반환한다', () => {
    expect(unwrapEnvelope({ code: '200', body: { value: 7 } })).toEqual({ value: 7 })
  })

  it('일반 JSON은 그대로 반환한다', () => {
    expect(unwrapEnvelope({ value: 7 })).toEqual({ value: 7 })
  })

  it('업무 오류를 ApiError로 변환한다', () => {
    expect(() => unwrapEnvelope({ code: 'BZ01', message: '실패', body: null })).toThrow(ApiError)
  })
})

describe('unwrapPageEnvelope', () => {
  it('목록 body와 pageInfo를 보존한다', () => {
    expect(
      unwrapPageEnvelope({
        code: '200',
        body: [{ id: 1 }],
        pageInfo: { pageNum: 2, pageSize: 20, totalCount: 41 },
      }),
    ).toEqual({ body: [{ id: 1 }], pageInfo: { pageNum: 2, pageSize: 20, totalCount: 41 } })
  })

  it('누락된 pageInfo에 안전한 기본값을 적용한다', () => {
    expect(unwrapPageEnvelope({ code: '200', body: [] }).pageInfo).toEqual({ pageNum: 1, pageSize: 10, totalCount: 0 })
  })

  it('totalCount만 주는 backend 계약에서는 요청한 페이지를 유지한다', () => {
    expect(
      unwrapPageEnvelope({ code: '200', body: [{ id: 1 }], pageInfo: { totalCount: 41 } }, { pageNum: 3, pageSize: 20 }).pageInfo,
    ).toEqual({ pageNum: 3, pageSize: 20, totalCount: 41 })
  })

  it('서버가 유효하지 않은 페이지 값을 주면 요청한 값으로 대체한다', () => {
    expect(
      unwrapPageEnvelope({ code: '200', body: [], pageInfo: { pageNum: 0, pageSize: Number('x') } }, { pageNum: 4, pageSize: 50 }).pageInfo,
    ).toEqual({ pageNum: 4, pageSize: 50, totalCount: 0 })
  })

  it('서버가 준 페이지 값이 요청 값보다 우선한다', () => {
    expect(
      unwrapPageEnvelope({ code: '200', body: [], pageInfo: { pageNum: 1, pageSize: 10, totalCount: 3 } }, { pageNum: 9, pageSize: 20 }).pageInfo,
    ).toEqual({ pageNum: 1, pageSize: 10, totalCount: 3 })
  })
})

describe('readPageRequest', () => {
  it('params의 페이지 값을 읽는다', () => {
    expect(readPageRequest({ keyword: 'a', pageNum: '3', pageSize: 20 })).toEqual({ pageNum: 3, pageSize: 20 })
  })

  it('params가 없거나 페이지 값이 유효하지 않으면 비운다', () => {
    expect(readPageRequest(undefined)).toEqual({})
    expect(readPageRequest({ pageNum: 0, pageSize: -1 })).toEqual({ pageNum: undefined, pageSize: undefined })
  })
})

describe('apiGetPage', () => {
  afterEach(() => vi.unstubAllGlobals())

  it('서버가 페이지 값을 생략해도 요청한 페이지로 응답을 해석한다', async () => {
    stubLocalStorage()
    configureHttp(runtimeConfig)

    const result = await apiGetPage<Array<{ id: number }>>('/library', {
      params: { pageNum: 3, pageSize: 20 },
      adapter: async (requestConfig) => ({
        data: { code: '200', body: [{ id: 41 }], pageInfo: { totalCount: 61 } },
        status: 200,
        statusText: 'OK',
        headers: {},
        config: requestConfig,
      }),
    })

    expect(result).toEqual({ body: [{ id: 41 }], pageInfo: { pageNum: 3, pageSize: 20, totalCount: 61 } })
  })
})

describe('extractTokenRecord', () => {
  it('기존 backend envelope의 회전 token을 읽는다', () => {
    expect(
      extractTokenRecord({
        code: '200',
        data: { access_token: 'next-access', refresh_token: 'next-refresh', type: '관리자' },
        body: { value: 7 },
      }),
    ).toEqual({ access_token: 'next-access', refresh_token: 'next-refresh', id_token: undefined, authority: '관리자' })
  })

  it('일반 data payload는 token으로 처리하지 않는다', () => {
    expect(extractTokenRecord({ code: '200', data: { value: 7 } })).toBeNull()
  })
})

describe('fallbackErrorMessage', () => {
  it('상태별로 다음 행동을 알려준다', () => {
    expect(fallbackErrorMessage({ code: 'ECONNABORTED', response: undefined })).toBe('요청 시간이 초과됐습니다.')
    expect(fallbackErrorMessage({ code: 'ERR_NETWORK', response: undefined })).toBe('서버에 연결하지 못했습니다. 네트워크 상태를 확인하십시오.')
    expect(fallbackErrorMessage({ code: undefined, response: { status: 401 } } as never)).toBe('세션이 만료됐습니다. 다시 로그인하십시오.')
    expect(fallbackErrorMessage({ code: undefined, response: { status: 403 } } as never)).toBe('이 작업을 수행할 권한이 없습니다.')
    expect(fallbackErrorMessage({ code: undefined, response: { status: 500 } } as never)).toBe('API 요청에 실패했습니다.')
  })

  it('기존 backend의 400 + 토큰 code도 세션 만료로 안내한다', () => {
    expect(fallbackErrorMessage({ code: undefined, response: { status: 400, data: { code: '403' } } } as never)).toBe(
      '세션이 만료됐습니다. 다시 로그인하십시오.',
    )
  })
})

describe('isSessionExpired', () => {
  function response(status: number, data: unknown = {}) {
    return { response: { status, data } } as never
  }

  it('HTTP 401을 세션 만료로 본다', () => {
    expect(isSessionExpired(response(401))).toBe(true)
  })

  // 기존 backend는 토큰 없음/만료/오류를 HTTP 400 + body code로 알린다.
  it('400 + 토큰 code를 세션 만료로 본다', () => {
    expect(isSessionExpired(response(400, { code: '401' }))).toBe(true)
    expect(isSessionExpired(response(400, { code: '403' }))).toBe(true)
    expect(isSessionExpired(response(400, { code: 405 }))).toBe(true)
  })

  it('그 밖의 400 업무 오류와 403 인가 실패는 세션을 만료로 보지 않는다', () => {
    expect(isSessionExpired(response(400, { code: 'BZ01' }))).toBe(false)
    expect(isSessionExpired(response(400, { code: '200' }))).toBe(false)
    expect(isSessionExpired(response(400))).toBe(false)
    expect(isSessionExpired(response(403, { code: '403' }))).toBe(false)
    expect(isSessionExpired(response(500))).toBe(false)
    expect(isSessionExpired({ response: undefined })).toBe(false)
  })
})

describe('세션 만료 응답', () => {
  afterEach(() => {
    setUnauthorizedHandler(null)
    setSessionGenerationSource(null)
    vi.unstubAllGlobals()
  })

  function requestWithStatus(status: number, data: unknown = {}) {
    return apiGet('/library', {
      adapter: async (requestConfig) => {
        throw new AxiosError('Request failed', AxiosError.ERR_BAD_REQUEST, requestConfig as InternalAxiosRequestConfig, null, {
          data,
          status,
          statusText: 'error',
          headers: {},
          config: requestConfig as InternalAxiosRequestConfig,
        })
      },
    })
  }

  it('401이면 세션 정리 handler를 호출하고 재로그인을 안내한다', async () => {
    stubLocalStorage()
    const onUnauthorized = vi.fn()
    setUnauthorizedHandler(onUnauthorized)
    configureHttp(runtimeConfig)

    await expect(requestWithStatus(401)).rejects.toMatchObject({
      name: 'ApiError',
      status: 401,
      message: '세션이 만료됐습니다. 다시 로그인하십시오.',
    })
    expect(onUnauthorized).toHaveBeenCalledTimes(1)
  })

  // 실제 backend는 세션이 끝나도 HTTP 401을 주지 않는다. 이 경로를 놓치면 캐시된 세션이 계속 유효해 보인다.
  it('기존 backend의 400 + 토큰 code에서도 세션 정리 handler를 호출한다', async () => {
    stubLocalStorage()
    const onUnauthorized = vi.fn()
    setUnauthorizedHandler(onUnauthorized)
    configureHttp(runtimeConfig)

    await expect(requestWithStatus(400, { code: '403' })).rejects.toMatchObject({
      name: 'ApiError',
      status: 400,
      code: '403',
      message: '세션이 만료됐습니다. 다시 로그인하십시오.',
    })
    expect(onUnauthorized).toHaveBeenCalledTimes(1)
  })

  it('400 업무 오류는 세션을 버리지 않는다', async () => {
    stubLocalStorage()
    const onUnauthorized = vi.fn()
    setUnauthorizedHandler(onUnauthorized)
    configureHttp(runtimeConfig)

    await expect(requestWithStatus(400, { code: 'BZ01', message: '요청 값을 확인하십시오.' })).rejects.toMatchObject({
      status: 400,
      message: '요청 값을 확인하십시오.',
    })
    expect(onUnauthorized).not.toHaveBeenCalled()
  })

  it('403은 인가 실패이므로 세션을 버리지 않는다', async () => {
    stubLocalStorage()
    const onUnauthorized = vi.fn()
    setUnauthorizedHandler(onUnauthorized)
    configureHttp(runtimeConfig)

    await expect(requestWithStatus(403)).rejects.toMatchObject({ status: 403, message: '이 작업을 수행할 권한이 없습니다.' })
    expect(onUnauthorized).not.toHaveBeenCalled()
  })

  it('서버가 준 message가 있으면 그대로 보여준다', async () => {
    stubLocalStorage()
    configureHttp(runtimeConfig)

    await expect(requestWithStatus(401, { code: 'auth.session.expired', message: '세션이 종료되었습니다.' })).rejects.toMatchObject({
      message: '세션이 종료되었습니다.',
      code: 'auth.session.expired',
    })
  })

  it('요청이 떠날 때의 세션 세대를 handler에 넘긴다', async () => {
    stubLocalStorage()
    const onUnauthorized = vi.fn()
    let generation = 5
    setSessionGenerationSource(() => generation)
    setUnauthorizedHandler(onUnauthorized)
    configureHttp(runtimeConfig)

    await expect(
      apiGet('/library', {
        adapter: async (requestConfig) => {
          // 요청이 떠난 뒤 세션이 새로 확보돼 세대가 올라간 상황이다.
          generation = 6
          throw new AxiosError('Request failed', AxiosError.ERR_BAD_REQUEST, requestConfig as InternalAxiosRequestConfig, null, {
            data: {},
            status: 401,
            statusText: 'error',
            headers: {},
            config: requestConfig as InternalAxiosRequestConfig,
          })
        },
      }),
    ).rejects.toBeInstanceOf(ApiError)

    expect(onUnauthorized).toHaveBeenCalledWith(5)
  })

  it('handler가 예외를 던져도 원래 API 오류를 그대로 전달한다', async () => {
    stubLocalStorage()
    setUnauthorizedHandler(() => {
      throw new Error('storage unavailable')
    })
    configureHttp(runtimeConfig)

    await expect(requestWithStatus(401)).rejects.toBeInstanceOf(ApiError)
  })
})

