import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { flushPromises, mount, type VueWrapper } from '@vue/test-utils'
import { createMemoryHistory, createRouter } from 'vue-router'
import type { LibraryDetail } from '@/api/models'

// 실제 Catalog API 배선은 유지하고 HTTP 경계만 제어한다. Envelope 파서 검증은 아니다.
vi.mock('@/config/runtime', () => ({ getRuntimeConfig: () => ({ mockMode: false }) }))
vi.mock('@/api/http', () => ({ apiGet: vi.fn(), apiGetPage: vi.fn() }))

import { apiGet, apiGetPage } from '@/api/http'
import CatalogView from './CatalogView.vue'

const A: LibraryDetail = { id: 1, title: 'A 제목', content: '<p>A 본문</p>', groupCode: 'NOTICE', viewYn: 'Y', notifyYn: 'N', viewCnt: 1, libraryFileList: [{ id: 11, fileName: 'A.pdf' }] }
const B: LibraryDetail = { ...A, id: 2, title: 'B 제목', content: '<p>B 본문</p>', libraryFileList: [{ id: 22, fileName: 'B.pdf' }] }
const mounted: VueWrapper[] = []

function deferred() {
  let resolve!: (value: LibraryDetail) => void
  let reject!: (reason: unknown) => void
  const promise = new Promise<LibraryDetail>((res, rej) => { resolve = res; reject = rej })
  return { promise, resolve, reject }
}

beforeEach(() => {
  vi.mocked(apiGet).mockReset()
  vi.mocked(apiGetPage).mockReset().mockResolvedValue({ body: [A, B], pageInfo: { pageNum: 1, pageSize: 10, totalCount: 2 } })
})
afterEach(() => { while (mounted.length) mounted.pop()?.unmount() })

async function mountView() {
  const router = createRouter({ history: createMemoryHistory(), routes: [{ path: '/catalog', component: CatalogView }] })
  await router.push('/catalog')
  await router.isReady()
  const wrapper = mount(CatalogView, { global: { plugins: [router] } })
  mounted.push(wrapper)
  await flushPromises()
  expect(apiGetPage).toHaveBeenCalledWith('/library', expect.objectContaining({ params: expect.objectContaining({ pageNum: 1, pageSize: 10 }) }))
  return { wrapper, router }
}
async function select(wrapper: VueWrapper, index = 0) {
  await wrapper.findAll('.title-button')[index]!.trigger('click')
  await flushPromises()
